('advanced-native-1276', '["phrase"]'::jsonb, '{"advanced-native-1276-v1-audio":{"type":"mc","answers":["The completed model was removed, but asking about a difficult sentence remained possible."],"options":["The tutor supplied a completed translation before each choice of wording.","The task tested copying the model rather than choosing language independently.","The learner had to submit the paragraph before discussing any difficulty with the tutor.","The completed model was removed, but asking about a difficult sentence remained possible."]},"advanced-native-1276-v2-reply":{"type":"mc","answers":["I had to make the language choices that the earlier model had guided.","The tutor remained available, but the paragraph itself was no longer worked out for me.","It stripped away the training wheels by removing the completed example.","There was no finished model to follow when I chose the wording."],"options":["I had to make the language choices that the earlier model had guided.","The tutor remained available, but the paragraph itself was no longer worked out for me.","It stripped away the training wheels by removing the completed example.","There was no finished model to follow when I chose the wording."]},"advanced-native-1276-v1-scene":{"type":"mc","answers":["The change does not fully strip away the training wheels, since the ready-made outline still guides the drawing."],"options":["The change does not fully strip away the training wheels, since the ready-made outline still guides the drawing.","The outline shows that the learner has already designed the whole image independently.","Keeping the outline means the step-by-step prompts are still being shown as well."]},"advanced-native-1276-v1-contrast":{"type":"mc","answers":["這個人已適合失去所有種類的支援。"],"options":["接下來需要較獨立地作出選擇。","這個人已適合失去所有種類的支援。","某項暫時的學習輔助被撤去。"]},"advanced-native-1276-v1-branch":{"type":"mc","answers":["The task strips away the training wheels of a finished model; asking one question does not make the tutor choose my wording."],"options":["I should avoid asking about the confusing sentence and choose wording I do not understand.","The task strips away the training wheels of a finished model; asking one question does not make the tutor choose my wording.","I should ask the tutor to settle each choice of wording before I attempt the paragraph."]},"advanced-native-1276-v1-final":{"type":"open","answers":["We can strip away the training wheels of the writing frame without removing access to the text. Let everyone compose the invitation independently, while the screen reader remains available.","Writing without the frame strips away the training wheels; losing the screen reader is a different issue. I support independent composition with the access tools each learner needs."],"options":[]}}'::jsonb),
