('advanced-native-1303', '["phrase"]'::jsonb, '{"advanced-native-1303-v1-audio":{"type":"mc","answers":["The aunt offered emotional comfort, while application advice remained a separate need."],"options":["The adviser had asked the speaker to deliver the letter to the kitchen.","The speaker decided not to make any further application.","The aunt offered emotional comfort, while application advice remained a separate need.","The aunt had already promised a place on the course."]},"advanced-native-1303-v2-reply":{"type":"mc","answers":["I wanted a little comfort before discussing another application.","She is someone I trust with disappointing news.","I needed to talk about how I felt, as well as work out the next practical step.","Her kitchen is where my heart goes first when I need someone to listen."],"options":["I wanted a little comfort before discussing another application.","She is someone I trust with disappointing news.","I needed to talk about how I felt, as well as work out the next practical step.","Her kitchen is where my heart goes first when I need someone to listen."]},"advanced-native-1303-v1-scene":{"type":"mc","answers":["Home can be where her heart goes first even if practical circumstances take her to a hotel before she gets there."],"options":["The account says she reached home first and only later decided to stay at the hotel.","Home can be where her heart goes first even if practical circumstances take her to a hotel before she gets there.","The hotel stay establishes that she wanted its company and comfort more than she wanted to return home."]},"advanced-native-1303-v1-contrast":{"type":"mc","answers":["這個人一定能替我解決所有實際問題。"],"options":["我也可能需要向別人尋求專業協助。","這是我本能想尋求情感連繫的人或地方。","這個人一定能替我解決所有實際問題。"]},"advanced-native-1303-v1-branch":{"type":"mc","answers":["No, she is where my heart goes first for comfort; I will ask the adviser about applying again."],"options":["No, she is where my heart goes first for comfort; I will ask the adviser about applyi