('advanced-native-1313', '["phrase"]'::jsonb, '{"advanced-native-1313-v1-audio":{"type":"mc","answers":["Smaller households account for a larger share, but visiting frequency is not established."],"options":["The report measures only the floor area of homes.","Smaller households account for a larger share, but visiting frequency is not established.","Every household now has fewer people than it had ten years ago.","Relatives visit less often because the smaller-home share has increased."]},"advanced-native-1313-v2-reply":{"type":"mc","answers":["It records a move towards smaller households.","One- and two-person homes make up more of the total than before.","The distribution has shifted towards homes with fewer residents.","The share of homes with only one or two residents has increased compared with ten years ago."],"options":["It records a move towards smaller households.","One- and two-person homes make up more of the total than before.","The distribution has shifted towards homes with fewer residents.","The share of homes with only one or two residents has increased compared with ten years ago."]},"advanced-native-1313-v1-scene":{"type":"mc","answers":["The comparable figures suggest a move towards smaller households."],"options":["The comparison establishes that family members feel less close.","The figures describe smaller rooms rather than fewer residents.","The comparable figures suggest a move towards smaller households."]},"advanced-native-1313-v1-contrast":{"type":"mc","answers":["一位朋友搬到較小單位，但同住人數沒有改變。"],"options":["兩個年份按相同定義列出的每戶人數分布。","一位朋友搬到較小單位，但同住人數沒有改變。","同一地區多年一人、二人及多人住戶的比例。"]},"advanced-native-1313-v1-branch":{"type":"mc","answers":["The report shows a move towards smaller households, but it does not measure how much relatives care for one another."],"options":["The numbers prove that all residents prefer living alone.","The report shows a move towards smaller households, but it does not measure how much relatives care for one another.","We can re