('advanced-native-1320', '["phrase"]'::jsonb, '{"advanced-native-1320-v1-audio":{"type":"mc","answers":["The roles could not be changed even when either person wanted to learn another task."],"options":["They could try another responsibility whenever they wished, but both preferred to keep the original jobs.","The roles could not be changed even when either person wanted to learn another task.","Both people freely chose their tasks and could revise the arrangement.","The account says neither person was ever asked to do any work."]},"advanced-native-1320-v2-reply":{"type":"mc","answers":["They were boxed into different roles with no room to learn each other’s tasks.","Their requests to try another responsibility were repeatedly refused.","The assigned jobs could not be reconsidered when their interests changed.","The problem was the lack of choice, rather than simply having different jobs."],"options":["They were boxed into different roles with no room to learn each other’s tasks.","Their requests to try another responsibility were repeatedly refused.","The assigned jobs could not be reconsidered when their interests changed.","The problem was the lack of choice, rather than simply having different jobs."]},"advanced-native-1320-v1-scene":{"type":"mc","answers":["Different tasks do not mean people are boxed into roles when they can choose and reconsider them."],"options":["The description says members must stay in the first group permanently.","Different tasks do not mean people are boxed into roles when they can choose and reconsider them.","Having different task names establishes that every member was refused a choice."]},"advanced-native-1320-v1-contrast":{"type":"mc","answers":["不詢問意願，直接命令兩人永久交換所有工作。"],"options":["問清兩人的意願，提供學習及重新商量分工的機會。","不詢問意願，直接命令兩人永久交換所有工作。","安排可先試做的新任務，之後一起檢視是否合適。"]},"advanced-native-1320-v1-branch":{"type":"mc","answers":["They need not be boxed into fixed roles; we can ask which tasks they want to try rather than order a complete swap."],"