('advanced-native-1324', '["phrase"]'::jsonb, '{"advanced-native-1324-v1-audio":{"type":"mc","answers":["They recorded different family recipes and their histories without declaring one the only proper version."],"options":["They decided that cousins were too young to record any family customs.","They recorded different family recipes and their histories without declaring one the only proper version.","They removed every variation before letting relatives describe the meal.","They required each relative to cook the same version at every festival."]},"advanced-native-1324-v2-reply":{"type":"mc","answers":["They are keepers of family tradition because they preserve the recipes and their stories.","Their recordings let later relatives hear how the meal was prepared.","They kept several versions instead of claiming one was the only authentic account.","They helped pass on the customs through actual documentation."],"options":["They are keepers of family tradition because they preserve the recipes and their stories.","Their recordings let later relatives hear how the meal was prepared.","They kept several versions instead of claiming one was the only authentic account.","They helped pass on the customs through actual documentation."]},"advanced-native-1324-v1-scene":{"type":"mc","answers":["He acts as a keeper of family tradition by preserving the recordings and sharing the songs."],"options":["He acts as a keeper of family tradition by preserving the recordings and sharing the songs.","He can preserve tradition only if every relative is required to sing.","The dates show which remembered lyrics were used at those times, so the other family versions can be left out of the record."]},"advanced-native-1324-v1-contrast":{"type":"mc","answers":["未經同意，把所有親屬的私人回憶公開上網。"],"options":["未經同意，把所有親屬的私人回憶公開上網。","邀請有興趣的人學習保存下來的做法。","在分享記錄時交代資料從誰而來。"]},"advanced-native-1324-v1-branch":{"type":"mc","answers":["Being a keeper of family tradition does not replace consent; keep those record